# Original feats for the new classes and for the optional Techniques rules.
# Format: (name, type, prerequisite, text)
FEATS = [
("Field Marshal", "General", "Level 4+, Orders feature",
 "+1 Intelligence or Charisma. You gain one extra Command Die. You can give Orders to an ally who can see or hear you within 60 feet of you, instead of 30 feet."),
("Master Brewer", "General", "Level 4+, Concoctions feature",
 "+1 Intelligence or Wisdom. When you prepare concoctions after a Long Rest, you prepare one more than normal. You can throw a bomb at a point within 60 feet of you, instead of 30 feet."),
("Steady Channel", "General", "Level 4+, Strain feature",
 "+1 Wisdom or Constitution. Your Strain Limit increases by 1. When you Overstrain, you can make a DC 15 Constitution saving throw. On a success, you don't gain the Exhaustion level."),
("Deep Bond", "General", "Level 4+, Bound Spirit feature",
 "+1 Charisma or Constitution. Your bound spirit's Hit Point maximum increases by an amount equal to your character level. You gain one extra Bond Point."),
("Battle Caller", "General", "Level 4+",
 "+1 Intelligence or Charisma. Choose one of these Orders from the Captain class: Rally!, Move!, Focus Fire!, or Brace!. You can give it as a Captain does, using a d6 as your Command Die and your Intelligence modifier where the Order uses it. You can do this a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."),
("Technique Adept", "General", "Level 4+, the Techniques optional rules",
 "+1 Strength, Dexterity, or Constitution. You learn two more techniques of your choice that you qualify for, and you gain one extra technique point."),
]
